-- Migration: Seed Official Kannada 14/09/2026, 15/09/2026, and 16/09/2026 Festival Schedules with Unified Main Venue Location

-- 1. Ensure table exists
CREATE TABLE IF NOT EXISTS public.festival_schedules (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title TEXT NOT NULL,
    description TEXT,
    schedule_date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME,
    venue TEXT,
    category TEXT DEFAULT 'pooja',
    is_published BOOLEAN DEFAULT true,
    sort_order INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Clear old schedule data
DELETE FROM public.festival_schedules;

